<script lang="ts">
 import {onMount} from 'svelte';
 import {themes,themeId,defaultBranding,type ThemeId,type Branding} from './lib/appearance';
 import {api,ApiError} from './lib/api';
 import {openContents,validateContent,dateLabel,isoDate,type Content} from './lib/content';
 import {savePending,removePending,listPending,type Pending} from './lib/outbox';
 import * as c from './lib/crypto';
 import {verifyArchive,heads,type Archive,type Verified,type Policy,type Event,type Member} from './lib/protocol';

 let status:any=$state(null),identity:c.Identity|null=$state(null),vault:c.Vault|null=$state(null),verified:Verified|null=$state(null);
 let pending:Pending[]=$state([]),draftId:string=$state(crypto.randomUUID()),draftAttachments:NonNullable<Content['attachments']>=$state([]);
 let badEvents:{event:Event;reason:string}[]=$state([]);
 let contents:Record<string,Content>=$state({}),keys:Record<number,Uint8Array<ArrayBuffer>>={},requests:any[]=$state([]),replica:any=$state({});
 let busy=$state(false),error=$state(''),notice=$state(''),password=$state(''),confirmPassword=$state(''),bootstrap=$state(''),expected=$state(''),restoreFile:File|undefined=$state(),restoreArchive:Archive|null=$state(null);
 let theme:ThemeId=$state(themeId(localStorage.getItem('nightbuoy-theme'))),branding:Branding=$state(defaultBranding);
 let policy:Policy=$state({name:'NightBuoy community',skin:'nightbuoy',admission:'approval',history:true,identity:'key'}),settings:Policy=$state({name:'NightBuoy community',skin:'nightbuoy',admission:'approval',history:true,identity:'key'});
 let route=$state(location.pathname),panel=$state('forum'),createKind=$state(''),title=$state(''),body=$state(''),description=$state(''),order=$state(0),files:FileList|undefined=$state(),editing:Event|null=$state(null),savedRecovery=$state(false),setupMode=$state('create');
 let selectedFile:HTMLInputElement=$state() as HTMLInputElement;
 let publisherCandidate=$state('');
 let resetBranch=$state(false),forkVault:c.Vault|null=$state(null),exclude=$state('');
 let publicPin=$state(new URLSearchParams(location.search).get('community')||'');
 const short=(id:string)=>`member-${id.slice(0,10)}`;
 const admin=$derived.by(()=>!status?.read_only&&!!identity&&verified?.view.members[identity.device.id]?.role==='administrator');
 const moderator=$derived.by(()=>!status?.read_only&&!!identity&&['administrator','moderator'].includes(verified?.view.members[identity.device.id]?.role||''));
 function setTheme(value:string){theme=themeId(value);document.documentElement.dataset.theme=theme;localStorage.setItem('nightbuoy-theme',theme);}
 const objects=$derived.by(()=>{if(!verified)return [];const ids=[...new Set(verified.events.map(e=>e.id))];return ids.map(id=>heads(verified!.events,id).at(-1)!).filter(e=>e.kind!=='delete'&&contents[e.hash]);});
 const boards=$derived(objects.filter(e=>e.kind==='board').sort((a,b)=>(contents[a.hash]?.order||0)-(contents[b.hash]?.order||0)||a.id.localeCompare(b.id)));
 const boardId=$derived(route.startsWith('/b/')?route.slice(3):'');
 const topicId=$derived(route.startsWith('/t/')?route.slice(3):'');
 const selectedTopic=$derived(objects.find(e=>e.id===topicId&&e.kind==='topic'));
 const selectedBoard=$derived(boards.find(e=>e.id===(selectedTopic?.parent||boardId)));
 let search=$state('');
 const results=$derived(search.trim()?objects.filter(e=>e.kind!=='board'&&((contents[e.hash].title||'')+' '+(contents[e.hash].body||'')).toLowerCase().includes(search.toLowerCase())).slice(0,100):[]);
 function lockView(){pending=[];identity=null;verified=null;contents={};badEvents=[];for(const key of Object.values(keys))key.fill(0);keys={};requests=[];password='';panel='forum';}
 async function run(fn:()=>Promise<void>){if(busy)return;busy=true;error='';notice='';try{await fn();}catch(e){if(e instanceof ApiError&&e.status===401)lockView();error=e instanceof Error?e.message:String(e);}finally{busy=false;}}
 function go(path:string){history.pushState({},'',path);route=path;createKind='';editing=null;search='';window.scrollTo(0,0);}
 function localVault(v:c.Vault){vault=v;localStorage.setItem('nightbuoy-vault',JSON.stringify(v));}
 function pin(){if(verified)localStorage.setItem('nightbuoy-pin',JSON.stringify({community:verified.community,tip:verified.tip}));}
 async function refreshStatus(){status=await api('/api/status');branding=await api<Branding>('/api/branding');if(status.read_only&&!status.configured)setupMode='restore';if(status.genesis){const p=JSON.parse(status.genesis.body)[3];policy=p;}}
 async function auth(){if(!identity)return;const challenge=await api('/api/challenge',{device:identity.device});await api('/api/login',{challenge:challenge.id,device:identity.device,signed:await c.signed(identity,challenge.body)});}
 async function load(){if(!identity)return;const who=identity;const me=await api('/api/me');if(identity!==who)return;if(!me.member||me.member.status!=='active'){verified=null;contents={};for(const key of Object.values(keys))key.fill(0);keys={};notice=me.member?.status==='revoked'?'This identity is revoked on this branch.':'Waiting for an administrator to approve membership and key access.';return;}
  const archive=await api<Archive>('/api/sync');const oldPin=JSON.parse(localStorage.getItem('nightbuoy-pin')||'null');const v=await verifyArchive(archive,oldPin||{community:vault?.community||publicPin,tip:vault?.checkpoint||''});if(vault?.community&&v.community!==vault.community)throw Error('This recovery identity belongs to a different community.');
  const nextKeys:Record<number,Uint8Array<ArrayBuffer>>={};for(const [epoch,grants] of Object.entries(v.view.grants)){if(grants[identity.device.id])nextKeys[Number(epoch)]=await c.openGrant(who,grants[who.device.id]);}
  const {contents:next,rejected}=await openContents(v.events,nextKeys);if(identity!==who){for(const key of Object.values(nextKeys))key.fill(0);return;}badEvents=rejected;
  for(const key of Object.values(keys))key.fill(0);keys=nextKeys;contents=next;verified=v;pin();const queued=await listPending(who.device.id,v.community);for(const item of queued)if(v.events.some(e=>e.hash===item.hash))await removePending(item.hash);if(identity!==who)return;pending=queued.filter(item=>!v.events.some(e=>e.hash===item.hash));settings={...v.view.policy};replica=await api('/api/replication');
  if(!status.read_only&&v.view.members[identity.device.id]?.role==='administrator')requests=await api('/api/requests');else requests=[];
 }
 async function login(){if(!vault)throw Error('Import your encrypted recovery file first.');identity=await c.unlock(vault,password);password='';await auth();await load();}
 async function makeIdentity(){if(password!==confirmPassword)throw Error('Passphrases do not match.');identity=await c.generate();const v=await c.lock(identity,password,status.community||'');localVault(v);await auth();}
 function recovery(){if(!vault)return;c.download(`nightbuoy-${vault.device.id.slice(0,10)}-recovery.json`,JSON.stringify(vault,null,2));savedRecovery=true;notice='Encrypted recovery file downloaded. Keep it and your passphrase separate from the forum host.';}
 async function newMember(){await makeIdentity();await api('/api/join',{device:identity!.device,signed:await c.signed(identity!,['nightbuoy-join',1,status.community,identity!.device])});password='';confirmPassword='';recovery();await load();}
 async function createCommunity(){if(status.consensus)policy={...policy,consensus:status.consensus};if(!identity)await makeIdentity();if(policy.identity==='forge')await api('/api/join',{device:identity!.device,signed:await c.signed(identity!,['nightbuoy-join',1,'',identity!.device])});const key=await c.newEpoch();const genesis=await c.signed(identity!,['nightbuoy-genesis',1,identity!.device,policy,status.publisher,[await c.grant(identity!.device,1,key)]]);const community=await c.hash(genesis.body);localVault(await c.lock(identity!,password,community,community));recovery();await api('/api/setup',genesis,{'x-bootstrap-token':bootstrap});bootstrap='';password='';confirmPassword='';localStorage.removeItem('nightbuoy-pin');await refreshStatus();await load();notice='Community created. Save your recovery file, then create your first board.';}
 async function readRecovery(event:globalThis.Event){const f=(event.target as HTMLInputElement).files?.[0];if(!f)return;if(f.size>30000)throw Error('Recovery file is too large.');const v=JSON.parse(await f.text());if(status.community&&v.community!==status.community)throw Error('This recovery file belongs to a different community.');localVault(v);notice='Recovery file loaded. Enter its passphrase to sign in.';}
 async function readRestore(){if(!restoreFile)throw Error('Choose an encrypted community archive.');if(restoreFile.size>64*1024*1024)throw Error('Archive exceeds the pilot 64 MiB limit.');const archive=JSON.parse(await restoreFile.text()) as Archive;const v=await verifyArchive(archive,{community:expected,tip:''});restoreArchive=archive;notice=`Verified ${v.events.length} encrypted records. Confirm the community fingerprint before restoring.`;}
 async function restore(){
  if(!restoreArchive)await readRestore();if(!expected)throw Error('Enter the trusted community fingerprint from an invitation or independent source.');
  let archive=restoreArchive!;if(status.consensus&&!resetBranch)throw Error('Starting on a new validator network requires an explicit separate branch. Select the branch reset option.');
  if(resetBranch){
   if(!forkVault)throw Error('Import a surviving member’s encrypted recovery file.');
   const v=await verifyArchive(archive,{community:expected,tip:''});const survivor=await c.unlock(forkVault,password);
   if(v.view.members[survivor.device.id]?.status!=='active')throw Error('This identity was not active at the selected checkpoint. Select an earlier retained checkpoint.');
   const excluded=exclude.split(',').map(s=>s.trim()).filter(Boolean);const epoch=v.view.epoch+1,key=await c.newEpoch();const grants=[];
   for(const m of Object.values(v.view.members))if(m.status==='active'&&!excluded.includes(m.device.id))grants.push(await c.grant(m.device,epoch,key));
   const control=await c.signed(survivor,['nightbuoy-control',1,v.community,v.authority,survivor.device.id,[...c.random()].map(n=>n.toString(16).padStart(2,'0')).join(''),'reconstitute',{exclude:excluded,publisher:status.publisher,epoch,grants,consensus:status.consensus??undefined,checkpoint_proof:archive.proof}]);
   const branch=await c.hash(control.body);archive={...archive,proof:undefined,controls:[...archive.controls,control],order:[...archive.order,branch]};
   if(!status.consensus)await verifyArchive(archive);localVault(forkVault);identity=survivor;
  }
  await api('/api/restore',archive,{'x-bootstrap-token':bootstrap,'x-community-fingerprint':expected});bootstrap='';await refreshStatus();
  if(resetBranch){localStorage.setItem('nightbuoy-pin',JSON.stringify({community:expected,tip:archive.order.at(-1)}));await auth();await load();password='';notice='A separate branch is active. Prior history is retained, former administrator privileges are reset, and this member administers the new branch.';}
  else notice='Community restored. Import your recovery file and sign in. An administrator can approve this host for publishing.';
 }

 async function sendControl(op:string,data:unknown){if(!identity||!verified)throw Error('Unlock an administrator identity.');const signed=await c.signed(identity,['nightbuoy-control',1,verified.community,verified.authority,identity.device.id,[...c.random()].map(n=>n.toString(16).padStart(2,'0')).join(''),op,data]);await api('/api/control',signed);await load();}
 async function publish(kind:string,parent:string,payload:Content,id:string=crypto.randomUUID(),previous=''){
  if(!identity||!verified)throw Error('Sign in first.');const epoch=verified.view.epoch,key=keys[epoch];if(!key)throw Error('Current key access is unavailable.');
  const event=await c.encryptEvent(identity,key,[1,verified.community,identity.device.id,verified.authority,epoch,kind,id,parent,previous,Date.now()],payload);
  const item:Pending={hash:await c.hash(event.body),owner:identity.device.id,community:verified.community,event,wrappedKey:(await c.grant(identity.device,epoch,key)).key,created:Date.now()};
  await savePending(item);pending=await listPending(item.owner,item.community);
  try{await api('/api/events',event);await removePending(item.hash);await load();return true;}catch(e){if(e instanceof ApiError&&e.status===401){lockView();throw e;}notice='Encrypted submission saved as pending. It is not confirmed. Open Account to retry, review or export it.';return false;}
 }
 async function retryPending(item:Pending){await api('/api/events',item.event);await removePending(item.hash);await load();notice='Submission accepted and verified.';}
 async function reviewPending(item:Pending){if(!identity||!verified)throw Error('Unlock your identity first.');const a=JSON.parse(item.event.body);const key=await c.openGrant(identity,item.wrappedKey);const payload=validateContent({kind:a[5]} as Event,await c.decryptEvent(key,item.event));key.fill(0);const existing=objects.find(e=>e.id===a[6]);compose(a[5],existing||null);draftId=a[6];title=payload.title||'';body=payload.body||'';description=payload.description||'';order=payload.order||0;draftAttachments=payload.attachments||[];panel='forum';if(a[5]==='topic')go('/b/'+a[7]);else if(a[5]==='reply')go('/t/'+a[7]);createKind=a[5];editing=existing||null;notice='Review this recovered draft before publishing against current permissions.';}

 async function attached(){const list:NonNullable<Content['attachments']>=[];let total=0;for(const f of Array.from(files||[])){total+=f.size;if(total>3*1024*1024)throw Error('Attachments must total at most 3 MiB per post.');list.push({name:f.name,size:f.size,data:c.b64(await f.arrayBuffer())});}return list;}
 async function savePost(){if((createKind!=='reply'&&!title.trim())||title.length>240||body.length>100000)throw Error('Enter a title (up to 240 characters) and keep the message below 100,000 characters.');if(createKind!=='board'&&!body.trim())throw Error('Enter a message.');const payload:Content=createKind==='board'?{title:title.trim(),description,order}:{...(editing?contents[editing.hash]:{}),title:createKind==='topic'?title.trim():undefined,body,attachments:[...(draftAttachments.length?draftAttachments:editing?contents[editing.hash]?.attachments||[]:[]),...await attached()]};const kind=createKind;const parent=editing?.parent||(kind==='board'?'':kind==='topic'?boardId:topicId);const id=editing?.id||draftId;const accepted=await publish(kind,parent,payload,id,editing?.hash||'');createKind='';editing=null;title='';body='';description='';files=undefined;if(accepted)notice='Submission accepted and verified. Check replica status for independent archive copies.';if(kind==='topic')go('/t/'+id);}
 function compose(kind:string,e:Event|null=null){draftId=e?.id||crypto.randomUUID();draftAttachments=[];createKind=kind;editing=e;title=e?contents[e.hash].title||'':'';body=e?contents[e.hash].body||'':'';description=e?contents[e.hash].description||'':'';order=e?contents[e.hash].order||0:boards.length;files=undefined;}
 async function rekey(op:string,member?:string){if(!verified)throw Error('Load the community first.');const epoch=verified.view.epoch+1,key=await c.newEpoch();const grants=[];for(const m of Object.values(verified.view.members))if(m.status==='active'&&m.device.id!==member)grants.push(await c.grant(m.device,epoch,key));await sendControl(op,{epoch,grants,...(member?{member}:{})});}
 async function admit(device:c.Device){if(!verified)throw Error('Load the community first.');const oldBoards=boards.map(b=>({event:b,payload:contents[b.hash]}));const p=verified.view.policy;const grants=[];let epoch=verified.view.epoch;if(p.history){for(const [e,key] of Object.entries(keys))grants.push(await c.grant(device,Number(e),key));}else{epoch++;const key=await c.newEpoch();for(const m of Object.values(verified.view.members))if(m.status==='active')grants.push(await c.grant(m.device,epoch,key));grants.push(await c.grant(device,epoch,key));}await sendControl('admit',{device,grants,epoch});if(!p.history)for(const b of oldBoards)await publish('board','',b.payload,b.event.id,b.event.hash);notice='Membership and encrypted key access granted.';}
 async function remove(e:Event){if(!confirm('Hide this content? Encrypted replicas and past readers may retain prior revisions.'))return;await publish('delete',e.parent,{body:'Removed'},e.id,e.hash);}
 function canEdit(e:Event){const root=verified?.events.find(x=>x.id===e.id&&!x.previous);return e.kind==='board'?admin:moderator||root?.author===identity?.device.id;}
 function quote(e:Event){compose('reply');body=`> ${short(e.author)} wrote:\n${(contents[e.hash].body||'').split('\n').map(s=>'> '+s).join('\n')}\n\n`;}
 async function signOut(){lockView();await api('/api/logout',{});notice='Signed out. Your local recovery vault remains encrypted.';}
 function exportArchive(){if(!verified)return;c.download(`nightbuoy-${verified.community.slice(0,12)}-${verified.tip.slice(0,12)}.json`,JSON.stringify(verified.archive));}
 async function importArchive(e:globalThis.Event){const f=(e.target as HTMLInputElement).files?.[0];if(!f)return;if(f.size>64*1024*1024)throw Error('Archive too large.');await api('/api/import',JSON.parse(await f.text()));await load();notice='Verified history caught up. Divergent chains are never merged.';}
 async function verifyForge(id:string){sessionStorage.setItem('nightbuoy-setup-policy',JSON.stringify(policy));location.assign('/auth/'+id+'?return_to='+encodeURIComponent(location.pathname));}
 onMount(()=>{setTheme(theme);let timer:ReturnType<typeof setInterval>;run(async()=>{const stored=localStorage.getItem('nightbuoy-vault');if(stored)vault=JSON.parse(stored);const draft=sessionStorage.getItem('nightbuoy-setup-policy');if(draft)policy=JSON.parse(draft);await refreshStatus();timer=setInterval(()=>{if(identity&&!busy)run(async()=>{await load();if(admin&&verified?.view.policy.admission==='automatic'){const pending=requests.find(r=>!verified!.view.members[r.device.id]&&(verified!.view.policy.identity!=='forge'||r.verified));if(pending)await admit(pending.device);}});},15000);});const pop=()=>{route=location.pathname;};window.addEventListener('popstate',pop);return()=>{clearInterval(timer);window.removeEventListener('popstate',pop);};});
</script>

<svelte:head><title>{verified?.view.policy.name||'Community forum'} · {branding.name}</title><link rel="icon" href={branding.favicon||'/nightbuoy.svg'}/>{#if branding.css}<link rel="stylesheet" href={branding.css}/>{/if}</svelte:head>
<a class="skip" href="#main">Skip to content</a>
<header class="nav"><div class="nav-inner"><a class="brand" href={branding.home}>{#if branding.logo}<img src={branding.logo} width="32" height="32" alt=""/>{/if}<span>{branding.name}</span></a><nav aria-label="Primary">{#each branding.links as link}<a href={link.href}>{link.label}</a>{/each}<button class="navlink current" onclick={()=>{panel='forum';go('/');}}>Forum</button><label class="appearance-picker"><span class="sr-only">NightBuoy appearance</span><select aria-label="NightBuoy appearance" value={theme} onchange={e=>setTheme(e.currentTarget.value)}>{#each themes as option}<option value={option.id}>{option.name}</option>{/each}</select></label>{#if identity}<button class="navlink" onclick={()=>panel=panel==='account'?'forum':'account'}>Account</button><button class="navlink" disabled={busy} onclick={()=>run(signOut)}>Sign out</button>{/if}</nav></div></header>

<main id="main" class="container" aria-busy={busy}>
 {#if error}<div class="alert error" role="alert">{error}</div>{/if}
 {#if notice}<div class="alert" role="status">{notice}</div>{/if}
 {#if busy}<div class="progress" role="status">Working securely…</div>{/if}
 {#if status?.configured}{#if status.branch&&status.branch!==status.community}<div class="alert">This deployment follows an explicitly reset branch. Branch fingerprint: <code>{status.branch}</code><button onclick={()=>{if(confirm('Trust this separate branch? It does not merge with your former branch. Verify its fingerprint independently.'))run(async()=>{localStorage.setItem('nightbuoy-pin',JSON.stringify({community:status.community,tip:status.branch}));if(identity)await load();notice='Branch explicitly selected.';});}}>Choose this branch</button></div>{/if}{/if}
 {#if !status}<p>Loading the community…</p>
 {:else if !status.configured}
  <div class="page-heading"><p class="eyebrow">Welcome to NightBuoy</p><h1>Create or restore your community.</h1><p class="muted">A forum that belongs to its members. The website is an address; the signed history and encryption keys travel with you.</p></div>
  <div class="tabs">{#if !status.read_only}<button class:chosen={setupMode==='create'} onclick={()=>setupMode='create'}>Create community</button>{/if}<button class:chosen={setupMode==='restore'} onclick={()=>setupMode='restore'}>Join / restore community</button></div>
  <section class="card setup"><label>Local setup token<input type="password" bind:value={bootstrap} autocomplete="off" placeholder="Paste the one-use token from your server"/></label><details class="setup-token-help"><summary>Where do I get the setup token?</summary><p>NightBuoy generates it automatically when the server starts for the first time. Run this in your local checkout:</p><code>npm run dev:token</code><p>For the operator Docker deployment, run on its server:</p><code>docker compose -f compose.production.yaml --env-file operator/deployment.env exec -T app cat /data/app/bootstrap-token</code><p>For a direct installation, read <strong>bootstrap-token</strong> inside NIGHTBUOY_DATA. The token can be used once. It prevents a visitor from taking over a new install.</p></details>
   {#if setupMode==='restore'}<h2>Restore from an independent copy</h2><p>Use a retained checkpoint to resume a branch. Divergent histories stay separate.</p><label>Trusted community fingerprint<input bind:value={expected} spellcheck="false" placeholder="64-character SHA-256 fingerprint"/></label><label>Encrypted community archive<input type="file" accept="application/json,.json" onchange={(e)=>{restoreFile=e.currentTarget.files?.[0];restoreArchive=null;}}/></label><label class="check"><input type="checkbox" bind:checked={resetBranch} disabled={status.read_only}/> Start a separate branch using a surviving member identity</label>
   {#if resetBranch}<p class="alert">This explicitly resets administrator authority on a separate branch. All former administrators become ordinary members. Other branches keep their own history and permissions; they never merge with this branch.</p><label>Surviving member recovery file<input type="file" accept="application/json,.json" onchange={(e)=>{const f=e.currentTarget.files?.[0];if(f)run(async()=>{if(f.size>30000)throw Error('Invalid recovery file size.');forkVault=JSON.parse(await f.text());});}}/></label><label>Recovery passphrase<input type="password" bind:value={password} autocomplete="current-password"/></label><label>Exclude identities from future access (full fingerprints, comma-separated)<textarea bind:value={exclude} rows="2"></textarea></label>{/if}
   <div class="actions"><button disabled={busy} onclick={()=>run(readRestore)}>Verify archive</button><button class="primary" disabled={busy||!bootstrap||!expected} onclick={()=>run(restore)}>Restore community</button></div>
   {:else}
    <h2>Community and membership</h2><label>Public community label<input bind:value={policy.name} maxlength="80"/></label><p class="hint">This label and branding are visible before sign-in. Board names and discussions are encrypted.</p>
    <label>New member admission<select bind:value={policy.admission}><option value="approval">Administrator approval</option><option value="automatic">Automatic while an unlocked administrator is online</option></select></label>
    <label>Joining requirements<select bind:value={policy.identity}><option value="forge">Verify an approved forge account</option><option value="key">Portable cryptographic identity only</option></select></label>
    <label class="check"><input type="checkbox" bind:checked={policy.history}/> New members may decrypt existing history</label><p class="hint">Otherwise new members receive future keys; existing board descriptions are republished for navigation. Revocation protects future messages, not copies already saved.</p>
    {#if policy.identity==='forge'}<h3>Verify the creator</h3>{#if status.providers.length===0}<p class="alert">Configure a real forge OAuth provider in the operator configuration before creating a forge-backed community.</p>{/if}{#each status.providers as p}<button onclick={()=>verifyForge(p.id)}>Verify with {p.label}</button>{/each}{/if}
    <h3>Protect your portable identity</h3><p>Your private keys are encrypted on this device. Neither this host nor the forge gets your passphrase. Keep the encrypted recovery file to sign in on another website.</p><label>Unique passphrase<input type="password" bind:value={password} autocomplete="new-password" minlength="20"/></label><label>Repeat passphrase<input type="password" bind:value={confirmPassword} autocomplete="new-password"/></label><button class="primary" disabled={busy||!bootstrap||password.length<20||password!==confirmPassword} onclick={()=>run(createCommunity)}>Create community & download recovery file</button>
   {/if}
  </section>
 {:else if !identity}
  <section class="welcome"><p class="eyebrow">Your community. Your keys.</p><h1>A place for the conversation.</h1><p>Sign in and unlock your keys to read, search, and join the discussion. Storage providers keep encrypted copies.</p></section>
  <div class="auth-grid"><section class="card"><h2>{vault?'Unlock your identity':'Already a member?'}</h2><p>Use your recovery file on any trusted deployment of this community.</p><input class="hidden" bind:this={selectedFile} type="file" accept="application/json,.json" onchange={(e)=>run(()=>readRecovery(e))}/><button onclick={()=>selectedFile.click()}>Import encrypted recovery file</button>{#if vault}<p class="hint">{short(vault.device.id)}</p><form onsubmit={(e)=>{e.preventDefault();run(login);}}><label>Passphrase<input type="password" bind:value={password} autocomplete="current-password"/></label><button class="primary" disabled={busy||!password}>Sign in & unlock</button></form>{/if}</section>
   <section class="card"><h2>New to the community?</h2><p>{policy.admission==='approval'?'An administrator approves membership and encrypted key access.':'An unlocked administrator grants encrypted key access to eligible new members.'}</p>{#if policy.identity==='forge'}{#each status.providers as p}<button onclick={()=>verifyForge(p.id)}>First, verify with {p.label}</button>{/each}{/if}<form onsubmit={(e)=>{e.preventDefault();run(newMember);}}><label>New unique passphrase<input type="password" bind:value={password} autocomplete="new-password" minlength="20"/></label><label>Repeat passphrase<input type="password" bind:value={confirmPassword} autocomplete="new-password"/></label><button disabled={busy||password.length<20||password!==confirmPassword}>Create identity & request membership</button></form></section></div>
  <p class="fingerprint">Community fingerprint <code>{status.community}</code></p>
 {:else if !verified}
  <section class="card narrow"><h1>Membership and key access</h1><p>Signed in as {short(identity.device.id)}. An administrator must grant this identity permission and encrypted keys before you can read.</p>{#if policy.identity==='forge'}{#each status.providers as p}<button onclick={()=>verifyForge(p.id)}>Verify with {p.label}</button>{/each}{/if}<button disabled={busy} onclick={()=>run(async()=>{await api('/api/join',{device:identity!.device,signed:await c.signed(identity!,['nightbuoy-join',1,status.community,identity!.device])});await load();})}>Submit / refresh membership request</button><button onclick={recovery}>Download encrypted recovery file</button><button disabled={busy} onclick={()=>run(load)}>Check approval</button></section>
 {:else if panel==='account'}
  <div class="page-heading"><p class="eyebrow">Private community identity</p><h1>{short(identity.device.id)}</h1><p class="muted">{verified.view.members[identity.device.id]?.role}. Your forge username and profile are not displayed.</p></div>
  {#if pending.length}<section class="card"><h2>Pending encrypted submissions</h2><p>These are not confirmed. They are stored encrypted in this browser. Private/Tor browser storage may disappear when the browser closes; export a copy if needed.</p><button onclick={()=>c.download('nightbuoy-pending.json',JSON.stringify(pending))}>Export encrypted pending submissions</button>{#each pending as item}<div class="member-row"><code>{item.hash.slice(0,16)}</code><div class="actions"><button disabled={busy} onclick={()=>run(()=>retryPending(item))}>Retry</button><button disabled={busy} onclick={()=>run(()=>reviewPending(item))}>Review draft</button><button disabled={busy} onclick={()=>run(async()=>{await removePending(item.hash);pending=pending.filter(p=>p.hash!==item.hash);})}>Discard local pending copy</button></div></div>{/each}</section>{/if}
  <section class="card"><h2>Recovery and independent copies</h2><div class="actions"><button onclick={recovery}>Download encrypted recovery file</button><button onclick={exportArchive}>Download encrypted community archive</button>{#if admin}<button disabled={busy} onclick={()=>run(async()=>{replica=await api('/api/replicate',{});})}>Sync independent backups now</button>{/if}</div><label>Passphrase to authenticate a fresh recovery checkpoint<input type="password" bind:value={password} autocomplete="current-password"/></label><button disabled={busy||password.length<20} onclick={()=>run(async()=>{await c.unlock(vault!,password);localVault(await c.lock(identity!,password,verified!.community,verified!.tip));password='';recovery();})}>Update recovery checkpoint & download</button><p>Keep your passphrase and recovery file. A forge login cannot recreate lost private keys.</p><p class="fingerprint">Community <code>{verified.community}</code><br/>Current checkpoint <code>{verified.tip}</code></p><p class="alert">{replica.copied?'An independent destination confirmed the current archive.':'Current history is stored locally. No independent copy of this exact tip has been confirmed.'}</p>{#if replica.error}<p class="error">{replica.error}</p>{/if}</section>
  {#if admin}
   <section class="card"><h2>Administrator setup and policies</h2><label>Public label<input bind:value={settings.name} maxlength="80"/></label><div class="columns"><label>Admission<select bind:value={settings.admission}><option value="approval">Administrator approval</option><option value="automatic">Automatic with online key steward</option></select></label><label>Identity requirement<select bind:value={settings.identity}><option value="forge">Approved forge at enrollment</option><option value="key">Portable identity only</option></select></label></div><label class="check"><input type="checkbox" bind:checked={settings.history}/> Grant new members existing history</label><button disabled={busy} onclick={()=>run(()=>sendControl('policy',settings))}>Save signed policy</button></section>
   <section class="card"><h2>Member requests</h2><p>Granting access encrypts community keys to the new member. They never pass through this service in plaintext.</p>{#each requests.filter(r=>!verified!.view.members[r.device.id]) as r}<div class="member-row"><div><strong>{short(r.device.id)}</strong><br/><span class="muted">{r.verified?'Forge verified on this host':'Key identity'}</span></div><button disabled={busy||(settings.identity==='forge'&&!r.verified)} onclick={()=>run(()=>admit(r.device))}>Approve & grant keys</button></div>{:else}<p class="muted">No pending requests on this host.</p>{/each}</section>
   <section class="card"><h2>Members and shared administration</h2><p>Administrators are peers. The creator has no permanent owner privilege. Removing a member rotates future encryption keys.</p>{#each Object.values(verified.view.members) as m}<div class="member-row"><div><strong>{short(m.device.id)}</strong><br/><span class="muted">{m.role} · {m.status}</span></div>{#if m.status==='active'}<div class="actions"><select aria-label={`Role for ${short(m.device.id)}`} value={m.role} disabled={busy} onchange={(e)=>run(()=>sendControl('role',{member:m.device.id,role:e.currentTarget.value}))}><option value="member">Member</option><option value="moderator">Moderator</option><option value="administrator">Administrator</option></select><button class="danger" disabled={busy} onclick={()=>{if(confirm('Revoke this member and rotate future keys? Existing saved content cannot be erased.'))run(()=>rekey('revoke',m.device.id));}}>Revoke</button></div>{/if}</div>{/each}</section>
   {#if badEvents.length}<section class="card"><h2>Isolated content</h2><p>These signed records could not be decrypted or validated. The evidence remains in history.</p>{#each badEvents as item}<div class="member-row"><div><code>{item.event.hash.slice(0,16)}</code><p>{item.reason} Author: {short(item.event.author)}</p></div>{#if heads(verified.events,item.event.id).some(e=>e.hash===item.event.hash)}<button disabled={busy} onclick={()=>run(()=>remove(item.event))}>Remove invalid content</button>{/if}</div>{/each}</section>{/if}
   <section class="card"><h2>Independent hosting</h2><p>Only publication keys are recorded in community history. Storage credentials, owner accounts and private routes stay with the operator.</p><label>Backend publication key<input bind:value={publisherCandidate} spellcheck="false"/></label><button disabled={busy||!publisherCandidate} onclick={()=>run(async()=>{await sendControl('publisher',{key:publisherCandidate.trim(),approved:true});publisherCandidate='';})}>Approve backend key</button>{#each verified.view.publishers as publisher}<div class="member-row"><code>{publisher}</code><button disabled={busy} onclick={()=>run(()=>sendControl('publisher',{key:publisher,approved:false}))}>Revoke backend key</button></div>{/each}{#if !verified.view.publishers.includes(status.publisher)}<p>This host is read-only until approved for publication.</p><button disabled={busy} onclick={()=>run(()=>sendControl('publisher',{key:status.publisher,approved:true}))}>Approve this host for signed member writes</button>{:else}<p>This host is approved for signed member writes.</p>{/if}<label>Catch up from encrypted archive<input type="file" accept="application/json,.json" onchange={(e)=>run(()=>importArchive(e))}/></label><button disabled={busy} onclick={()=>run(()=>rekey('rotate'))}>Rotate future keys</button><p class="hint">Catching up accepts only a compatible chain prefix. A divergent branch requires an explicit reset on a separate deployment. Keep the previous archive.</p></section>
  {/if}
 {:else}
  {#if badEvents.length}<div class="alert">{badEvents.length} encrypted record(s) could not be opened and were isolated. Other discussions remain available.</div>{/if}<div class="forum-top"><div><p class="eyebrow">Community forum</p><h1>{selectedTopic?contents[selectedTopic.hash].title:selectedBoard?contents[selectedBoard.hash].title:verified.view.policy.name}</h1><p class="muted">{selectedBoard?contents[selectedBoard.hash].description:'Shared knowledge. Independent homes. One conversation.'}</p></div><div class="account-chip"><span class="avatar">{identity.device.id.slice(0,2)}</span><div>{short(identity.device.id)}<small>{verified.view.members[identity.device.id]?.role}</small></div></div></div>
  <div class="toolbar"><div class="breadcrumbs"><button class="text" onclick={()=>go('/')}>All boards</button>{#if selectedBoard}<span>/</span><button class="text" onclick={()=>go('/b/'+selectedBoard!.id)}>{contents[selectedBoard.hash].title}</button>{/if}{#if selectedTopic}<span>/</span><span>Topic</span>{/if}</div><label class="search"><span class="sr-only">Search decrypted discussions</span><input type="search" placeholder="Search this community…" bind:value={search}/></label></div>
  {#if status.read_only}<div class="alert">This is a private read-only copy. No administrator approval or registration is required. Use a publishing frontend to contribute.</div>{:else if !verified.view.publishers.includes(status.publisher)}<div class="alert">This frontend is read-only. An administrator can approve this host from Account.</div>{/if}
  {#if search.trim()}<section class="card"><h2>Search results</h2><p class="hint">Search stays on this device.</p>{#each results as e}<button class="result" onclick={()=>go('/t/'+(e.kind==='topic'?e.id:e.parent))}><strong>{contents[e.hash].title||'Reply'}</strong><span>{contents[e.hash].body?.slice(0,180)}</span></button>{:else}<p>No matching discussions in your accessible history.</p>{/each}</section>
  {:else if topicId&&selectedTopic}
   <div class="section-heading"><span>{objects.filter(e=>e.kind==='reply'&&e.parent===topicId).length} replies</span><button class="primary" disabled={busy||status.read_only||!verified.view.publishers.includes(status.publisher)} onclick={()=>compose('reply')}>Reply to topic</button></div>
   {#each [selectedTopic,...objects.filter(e=>e.kind==='reply'&&e.parent===topicId).sort((a,b)=>verified!.archive.order.indexOf(a.hash)-verified!.archive.order.indexOf(b.hash))] as post}<article class="card post"><div class="post-meta"><span class="avatar">{post.author.slice(0,2)}</span><strong>{short(post.author)}</strong><time datetime={isoDate(post.created)}>{dateLabel(post.created)}</time>{#if post.previous}<small>edited</small>{/if}</div><div class="post-body">{contents[post.hash].body}</div>{#each contents[post.hash].attachments||[] as f}<button class="attachment" onclick={()=>c.download(f.name,c.un64(f.data),'application/octet-stream')}>↓ {f.name} <small>({Math.ceil(f.size/1024)} KiB)</small></button>{/each}<div class="post-actions"><button class="text" onclick={()=>quote(post)}>Quote</button>{#if canEdit(post)}<button class="text" onclick={()=>compose(post.kind,post)}>Edit</button><button class="text danger" onclick={()=>run(()=>remove(post))}>Remove</button>{/if}</div></article>{/each}
  {:else if boardId&&selectedBoard}
   <div class="section-heading"><span>{objects.filter(e=>e.kind==='topic'&&e.parent===boardId).length} topics</span><button class="primary" disabled={busy||status.read_only||!verified.view.publishers.includes(status.publisher)} onclick={()=>compose('topic')}>New topic</button></div><section class="list">{#each objects.filter(e=>e.kind==='topic'&&e.parent===boardId).reverse() as topic}<button class="list-row" onclick={()=>go('/t/'+topic.id)}><div class="topic-icon">☷</div><div class="row-body"><h2>{contents[topic.hash].title}</h2><p>{short(topic.author)} · {new Date(topic.created).toLocaleDateString()}</p></div><span class="count">{objects.filter(e=>e.kind==='reply'&&e.parent===topic.id).length}<small>replies</small></span></button>{:else}<div class="empty"><h2>Start the conversation.</h2><p>This board has no topics in your accessible history.</p></div>{/each}</section>
  {:else if boardId||topicId}<section class="card empty"><h2>{pending.some(p=>JSON.parse(p.event.body)[6]===(topicId||boardId))?'Submission pending':'Content unavailable'}</h2><p>This page may have been removed or belong to history you cannot decrypt.</p><button onclick={()=>go('/')}>Back to boards</button></section>
  {:else}
   <div class="section-heading"><span>Discussion boards</span>{#if admin}<button class="primary" disabled={busy||status.read_only||!verified.view.publishers.includes(status.publisher)} onclick={()=>compose('board')}>New board</button>{/if}</div><section class="list">{#each boards as board}<div class="board-row"><button class="list-row" onclick={()=>go('/b/'+board.id)}><div class="topic-icon">▤</div><div class="row-body"><h2>{contents[board.hash].title}</h2><p>{contents[board.hash].description}</p></div><span class="count">{objects.filter(e=>e.kind==='topic'&&e.parent===board.id).length}<small>topics</small></span></button>{#if admin}<button class="text board-edit" onclick={()=>compose('board',board)}>Edit board</button>{/if}</div>{:else}<div class="empty"><h2>{admin?'Make room for the first conversation.':'Your community is getting started.'}</h2><p>{admin?'Create a board to organize topics and replies.':'An administrator will create discussion boards here.'}</p></div>{/each}</section>
  {/if}
  {#if createKind}<section class="card composer"><div class="section-heading"><h2>{editing?'Edit':createKind==='reply'?'Write a':'New'} {createKind}</h2><button class="text" onclick={()=>{createKind='';editing=null;}}>Cancel</button></div><form onsubmit={(e)=>{e.preventDefault();run(savePost);}}>{#if createKind!=='reply'}<label>{createKind==='board'?'Board name':'Topic title'}<input bind:value={title} maxlength="240" required/></label>{/if}{#if createKind==='board'}<label>Description<textarea bind:value={description} rows="3" maxlength="2000"></textarea></label><label>Display order<input type="number" bind:value={order}/></label>{:else}<label>Message<textarea bind:value={body} rows="8" maxlength="100000" required></textarea></label><label>Attachments (up to 3 MiB total)<input type="file" multiple bind:files/></label><p class="hint">Text and attachments are encrypted on this device before upload. Messages display as plain text.</p>{/if}<button class="primary" disabled={busy}>{editing?'Save revision':'Publish '+createKind}</button></form></section>{/if}
  {#if pending.length}<div class="alert">{pending.length} encrypted submission(s) await confirmation. Manage them in Account.</div>{/if}<div class="forum-status"><span class:ok={replica.copied}>●</span> {replica.copied?'Current history has a confirmed independent copy':'Local history · independent replication pending'}<button class="text" onclick={()=>run(load)}>Refresh</button></div>
 {/if}
</main>
<footer><div class="container footer-inner"><div><strong>{branding.name}</strong><p>{branding.tagline}</p></div><div><span>Powered by NightBuoy</span><p>Encrypted content · Portable identities · Independent replicas</p></div></div></footer>
